package com.aetherforge.service;
import com.aetherforge.repo.MachineRepository;import com.aetherforge.repo.OperationalRepository;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CopilotService {private final MachineRepository machines;private final OperationalRepository ops;public CopilotService(MachineRepository m,OperationalRepository o){this.machines=m;this.ops=o;}public Map<String,Object> ask(String q){String s=q.toLowerCase();String answer;List<Map<String,Object>> sources=new ArrayList<>();if(s.contains("fail")||s.contains("risk")){var ms=ops.predictions();var top=ms.isEmpty()?null:ms.get(0);answer=top==null?"I don't have enough available factory data to determine that.":"The highest current failure risk is "+top.get("machine_code")+" at "+String.format("%.0f",((Number)top.get("failure_probability")).doubleValue()*100)+"%. Primary evidence: "+top.get("explanation");sources.add(Map.of("type","factory-data","label","Failure predictions"));}else if(s.contains("energy")){answer="The energy view is grounded in the backend energy metrics. Open Energy Intelligence for machine and line comparisons, baselines, and anomalies.";sources.add(Map.of("type","factory-data","label","Energy metrics"));}else if(s.contains("line 3")||s.contains("production")){answer="Production is available from the last 7 days of backend production metrics, including target, actual, OEE, quality, downtime and scrap.";sources.add(Map.of("type","factory-data","label","Production metrics"));}else if(s.contains("cnc-07")||s.contains("m-07")){var m=machines.list("CNC-07",null);answer=m.isEmpty()?"I don't have enough available factory data to determine that.":"CNC-07 is in DEMO/SIMULATION degradation monitoring. The backend reports rising vibration/temperature and elevated maintenance risk.";sources.add(Map.of("type","factory-data","label","Machine M-07"));}else{answer="I can answer grounded operational questions using factory status, machines, predictions, alerts, maintenance, production, energy and the knowledge base. I will not invent readings or history.";}return Map.of("mode","DEMO/SIMULATION","answer",answer,"sources",sources,"grounded",true);}}
